const data = $input.first().json;
const b = data.body || {};
const headers = data.headers || {};
const secret = headers['x-webhook-secret'];
if ($env.CONTACT_WEBHOOK_SECRET && secret !== $env.CONTACT_WEBHOOK_SECRET) {
  throw new Error('invalid webhook secret');
}
const esc = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const subject = ('[Site] ' + (b.subject || 'Novo contato') + ' - ' + (b.name || '')).trim();
const html = '<h2>Novo contato pelo site</h2>' +
  '<p><b>Nome:</b> ' + esc(b.name) + '</p>' +
  '<p><b>Email:</b> ' + esc(b.email) + '</p>' +
  '<p><b>Assunto:</b> ' + esc(b.subject) + '</p>' +
  '<p><b>Mensagem:</b><br>' + esc(b.message).replace(/\n/g, '<br>') + '</p>';
return [{ json: {
  from: 'Contato Site <contato@bcmtech.com.br>',
  to: ['contato@bcmtech.com.br'],
  reply_to: b.email || 'contato@bcmtech.com.br',
  subject: subject,
  html: html
} }];
